import random

def has_cycle_of_length_less_than_6(adj, n):
    # Check for cycles of length 3, 4, 5
    for start_node in range(n):
        # BFS to find cycles
        queue = [(start_node, -1, 0)] # (current_node, parent, depth)
        visited = {start_node: 0}
        while queue:
            u, p, d = queue.pop(0)
            if d >= 5:
                continue
            for v in adj[u]:
                if v == p:
                    continue
                if v in visited:
                    # Cycle found
                    if visited[v] + d + 1 < 6:
                        return True
                else:
                    visited[v] = d + 1
                    queue.append((v, u, d + 1))
    return False

def solve():
    n = 27
    adj = [set() for _ in range(n)]
    edges = []

    # Try to build a 3-regular graph
    # We can use a randomized approach

    for _ in range(10000):
        # Reset
        adj = [set() for _ in range(n)]
        edges = []

        # Try to add edges
        possible_edges = []
        for i in range(n):
            for j in range(i + 1, n):
                possible_edges.append((i, j))
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if len(adj[u]) < 3 and len(adj[v]) < 3:
                # Check if adding (u, v) creates a cycle of length < 6
                adj[u].add(v)
                adj[v].add(u)
                if has_cycle_of_length_less_than_6(adj, n):
                    adj[u].remove(v)
                    adj[v].remove(u)
                else:
                    edges.append((u, v))

            # Check if all vertices have degree 3
            if all(len(adj[i]) == 3 for i in range(n)):
                return edges
    return None

