import networkx as nx
import random

def find_graph():
    n = 27
    # Try to build a 3-regular graph with girth >= 6
    # A known 3-regular graph with girth 6 is the Heawood graph (14 vertices)
    # We need 27 vertices.
    # Let's try a randomized approach with a constraint solver or just more efficient search.

    # Using a simple greedy approach with backtracking or just random construction
    for _ in range(100):
        G = nx.Graph()
        G.add_nodes_from(range(n))

        # Try to add edges
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                edges.append((i, j))
        random.shuffle(edges)

        for u, v in edges:
            if G.degree[u] < 3 and G.degree[v] < 3:
                G.add_edge(u, v)
                # Check girth
                try:
                    if nx.shortest_cycle_length(G) < 6:
                        G.remove_edge(u, v)
                except nx.NetworkXNoCycle:
                    pass

            if G.number_of_edges() == (3 * n) // 2:
                break

        if G.number_of_edges() == (3 * n) // 2 and all(d == 3 for _, d in G.degree()):
            return list(G.edges())
    return None

