def check_graph(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check degrees
    for i in range(n):
        if not (3 <= len(adj[i]) <= 5):
            return False, f"Vertex {i} has degree {len(adj[i])}"

    # Check girth
    for start_node in range(n):
        dist = {start_node: 0}
        parent = {start_node: None}
        queue = [start_node]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    if dist[u] + dist[v] + 1 < 6:
                        return False, f"Cycle of length {dist[u] + dist[v] + 1} found"
    return True, "OK"

